import { createPreviewIcon } from './app-icons.mjs';
import { renderAppEmptyState } from './app-empty-state.mjs';
import { TMRW_VOICE_PRESETS } from '../domain/voice/voice-preset-catalog.mjs';

const node = (document, tag, text = '') => { const value = document.createElement(tag); if (text) value.textContent = text; return value; };
const languageLabel = value => value === 'en' ? 'English' : value === 'ja' ? 'Japanese' : 'Auto';
const deliveryLabel = value => value === 'soft' ? 'Soft' : value === 'expressive' ? 'Expressive' : 'Natural';

function copyBlock(document, title, detail = '') {
  const copy = node(document, 'span'); copy.className = 'tmrw-v3-voice-copy'; copy.append(node(document, 'strong', title)); if (detail) copy.append(node(document, 'small', detail)); return copy;
}

function toggleRow(document, { label, detail = '', pressed, setting, onClick, disabled = false }) {
  const button = node(document, 'button'); button.type = 'button'; button.className = 'tmrw-v3-voice-row tmrw-v3-voice-toggle'; button.dataset.setting = setting; button.setAttribute('aria-pressed', String(Boolean(pressed))); button.disabled = Boolean(disabled);
  const control = node(document, 'span'); control.className = 'tmrw-v3-voice-switch'; control.append(node(document, 'i')); button.append(copyBlock(document, label, detail), control);
  if (!button.disabled) button.addEventListener('click', () => onClick?.(!pressed)); return button;
}

function choiceGroup(document, { title, detail = '', values, selected, datasetKey, onSelect, disabled = false }) {
  const section = node(document, 'section'); section.className = 'tmrw-v3-voice-choice'; section.append(copyBlock(document, title, detail));
  const buttons = node(document, 'div'); buttons.className = 'tmrw-v3-voice-choice-buttons';
  for (const value of values) { const label = datasetKey.toLowerCase().includes('delivery') ? deliveryLabel(value) : languageLabel(value); const button = node(document, 'button', label); button.type = 'button'; button.dataset[datasetKey] = value; button.setAttribute('aria-pressed', String(value === selected)); button.disabled = Boolean(disabled); if (!button.disabled) button.addEventListener('click', () => onSelect?.(value)); buttons.append(button); }
  section.append(buttons); return section;
}

function textField(document, { value = '', placeholder, actionLabel, action, disabled, ariaLabel = null }) {
  const row = node(document, 'div'); row.className = 'tmrw-v3-voice-field'; const input = node(document, 'input'); input.type = 'text'; input.value = value; input.placeholder = placeholder; input.disabled = Boolean(disabled); if (ariaLabel) input.setAttribute('aria-label', ariaLabel); const save = node(document, 'button', actionLabel); save.type = 'button'; save.disabled = Boolean(disabled); if (!save.disabled) save.addEventListener('click', () => action?.(input.value)); row.append(input, save); return row;
}

export function renderVoiceSetup({ document, settings, capability, runtimeHealth = null, runtimeBusy = false, managerHealth = null, managerBusy = false, installedProfiles = [], cloneState = null, previewBusyId = null, roster = [], selectedActorId = null, selectedIdentity = null, baseProfile = null, instanceOverride = null, resolvedProfile = null, onToggleVoiceCalls, onToggleBotVoice, onToggleCaptions, onSetDefaultLanguage, onSetDefaultDelivery, onSaveRuntimeBaseUrl, onTestRuntime, onCheckManager = null, onInstallLocalVoice = null, onSelectActor, onSaveBaseName, onSetBaseLanguage, onToggleBaseLock, onToggleOverride, onSaveOverrideName, onSetOverrideLanguage, onUploadClone = null, onConfirmClone = null, onPreviewVoice = null }) {
  const runtimeReady = runtimeHealth?.ready === true || (capability?.runtimeAvailable === true && capability?.runtimeStatus === 'available');
  const runtimeConfigured = capability?.configured === true;
  const root = node(document, 'section'); root.className = 'tmrw-v3-voice-settings'; root.dataset.phase = '19'; root.dataset.voiceReady = String(runtimeReady); root.dataset.voiceConfigured = String(runtimeConfigured);

  const status = node(document, 'section'); status.className = 'tmrw-v3-voice-card tmrw-v3-voice-status'; const mark = node(document, 'span'); mark.className = 'tmrw-v3-voice-status-icon'; mark.append(createPreviewIcon({ document, name: 'voice', size: 23 })); const statusCopy = node(document, 'div'); statusCopy.append(node(document, 'small', 'TMRW LOCAL VOICE'), node(document, 'h3', runtimeReady ? 'พร้อมใช้งาน' : (runtimeConfigured ? 'พร้อมตั้งค่า' : 'ยังไม่พร้อมใช้งาน')), node(document, 'p', runtimeReady ? 'ตั้งค่าเสียงสำหรับการโทรของ TMRW Phone' : (runtimeConfigured ? 'ระบบจะตรวจ TMRW Local Voice ก่อนสร้างเสียง ถ้ายังไม่พร้อมจะแสดงข้อความตามปกติ' : 'ติดตั้ง Local Voice เพื่อโทรด้วยเสียงแบบฟรีถาวร'))); status.append(mark, statusCopy); root.append(status);

  const setup = node(document, 'section'); setup.className = 'tmrw-v3-voice-card tmrw-v3-voice-install'; setup.append(node(document, 'h4', 'ติดตั้งและอัปเดต'));
  setup.append(copyBlock(document, managerHealth?.ready ? 'Voice Manager พร้อมแล้ว' : 'ตรวจการติดตั้งในเครื่อง', managerHealth?.ready ? (managerHealth.runtime?.ready ? 'Runtime พร้อมโทร' : 'พร้อมดาวน์โหลดหรือเปิด Runtime') : 'ติดตั้งครั้งเดียว จากนั้นจัดการแพ็กเสียงในแอปได้'));
  const setupActions = node(document, 'div'); const check = node(document, 'button', managerBusy ? 'กำลังตรวจ…' : 'ตรวจอีกครั้ง'); check.type = 'button'; check.disabled = managerBusy || typeof onCheckManager !== 'function'; check.addEventListener('click', () => onCheckManager?.()); const install = node(document, 'button', managerBusy ? 'กำลังทำงาน…' : 'ติดตั้ง Local Voice'); install.type = 'button'; install.disabled = managerBusy || typeof onInstallLocalVoice !== 'function'; install.addEventListener('click', () => onInstallLocalVoice?.()); setupActions.append(check, install); setup.append(setupActions); root.append(setup);
  if (managerHealth?.ready === false) setup.append(node(document, 'p', 'ถ้าปิด Termux ระบบเสียงจะหยุดด้วย เปิด Termux แล้วรัน ~/.tmrw-voice/current/bin/START-TMRW-VOICE-SERVICES.sh ก่อนอัปโหลดคลิปหรือโทร'));

  const general = node(document, 'section'); general.className = 'tmrw-v3-voice-card'; general.append(node(document, 'h4', 'การโทรด้วยเสียง'));
  general.append(toggleRow(document, { label: 'Voice Calls', detail: runtimeReady ? 'เล่นเสียงพร้อมข้อความในการโทร' : (runtimeConfigured ? 'เปิดไว้ได้ ระบบจะตรวจ Local Voice ตอนใช้งานจริง' : 'ยังใช้ไม่ได้ในขณะนี้'), pressed: settings.voiceCallsEnabled, setting: 'voice-calls', onClick: onToggleVoiceCalls, disabled: !runtimeConfigured }));
  general.append(toggleRow(document, { label: 'เสียงของตัวละคร', detail: runtimeReady ? 'ใช้เสียงเมื่อตัวละครโทรหา' : (runtimeConfigured ? 'ถ้า Voice ไม่พร้อม Call จะใช้ข้อความตามปกติ' : 'ยังใช้ไม่ได้ในขณะนี้'), pressed: settings.botCallsWithVoice, setting: 'bot-calls-with-voice', onClick: onToggleBotVoice, disabled: !runtimeConfigured }));
  general.append(toggleRow(document, { label: 'คำบรรยายภาษาไทย', detail: 'เปิดหรือปิดได้ระหว่างสาย', pressed: settings.voiceCaptionsEnabled !== false, setting: 'voice-captions', onClick: onToggleCaptions, disabled: !runtimeConfigured }));
  general.append(choiceGroup(document, { title: 'ภาษาที่ใช้ในการโทรตอนนี้', detail: 'ใช้กับตัวละครทุกคน • เลือกได้ครั้งละหนึ่งภาษาและสลับระหว่างสายได้', values: ['en', 'ja'], selected: settings.voiceLanguagePreference === 'ja' ? 'ja' : 'en', datasetKey: 'voiceLanguage', onSelect: onSetDefaultLanguage, disabled: !runtimeConfigured }));
  root.append(general);

  const profiles = node(document, 'section'); profiles.className = 'tmrw-v3-voice-card tmrw-v3-voice-profiles'; profiles.append(node(document, 'h4', 'เสียงของตัวละคร'));
  if (roster.length === 0) profiles.append(renderAppEmptyState({ document, app: 'voice', compact: true }));
  else { const actors = node(document, 'div'); actors.className = 'tmrw-v3-voice-actors'; for (const item of roster) { const button = node(document, 'button', item.label); button.type = 'button'; button.dataset.voiceActorId = item.actorId; button.setAttribute('aria-pressed', String(item.actorId === selectedActorId)); button.addEventListener('click', () => onSelectActor?.(item)); actors.append(button); } profiles.append(actors); }

  if (selectedIdentity) {
    const base = node(document, 'section'); base.className = 'tmrw-v3-voice-profile-card'; base.dataset.voiceProfileKind = 'actor-base'; base.append(copyBlock(document, selectedIdentity.label, 'ค่าเสียงหลักของตัวละคร'));
    const selectedPreset = TMRW_VOICE_PRESETS.find(preset => preset.id === baseProfile?.profileName) || null;
    const selector = node(document, 'section'); selector.className = 'tmrw-v3-voice-preset-selector'; selector.append(copyBlock(document, 'TMRW Presets', selectedPreset ? `เลือกอยู่: ${selectedPreset.name}` : 'เสียงชาย 12 • เสียงหญิง 12'));
    for (const family of ['male', 'female']) { const group = node(document, 'details'); group.className = 'tmrw-v3-voice-preset-group'; if (selectedPreset?.family === family) group.open = true; group.append(node(document, 'summary', family === 'male' ? 'เสียงชาย 12 แบบ' : 'เสียงหญิง 12 แบบ')); const cards = node(document, 'div'); cards.className = 'tmrw-v3-voice-preset-cards'; for (const preset of TMRW_VOICE_PRESETS.filter(row => row.family === family)) { const row = node(document, 'div'); row.className = 'tmrw-v3-voice-preset-row'; row.setAttribute('aria-selected', String(preset.id === baseProfile?.profileName)); const choose = node(document, 'button'); choose.type = 'button'; choose.dataset.voicePresetId = preset.id; choose.append(node(document, 'strong', preset.name), node(document, 'small', `${preset.description.th} • ${preset.tags.th.join(' · ')}`)); choose.addEventListener('click', () => onSaveBaseName?.(preset.id)); const play = node(document, 'button', previewBusyId === preset.id ? '…' : '▶'); play.type = 'button'; play.className = 'tmrw-v3-voice-preview'; play.setAttribute('aria-label', `ฟังเสียง ${preset.name}`); play.disabled = previewBusyId === preset.id; play.addEventListener('click', () => onPreviewVoice?.(preset.id, settings.voiceLanguagePreference === 'ja' ? 'ja' : 'en')); row.append(choose, play); cards.append(row); } group.append(cards); selector.append(group); }
    const clones = installedProfiles.filter(profile => profile.kind === 'clone'); if (!selectedPreset && baseProfile?.profileName && !clones.some(profile => profile.id === baseProfile.profileName)) selector.append(copyBlock(document, 'เสียงโคลนที่เคยเลือก', `${baseProfile.profileName} • เปิด Local Voice เพื่อตรวจไฟล์`)); if (clones.length) { const group = node(document, 'details'); group.className = 'tmrw-v3-voice-preset-group'; group.open = clones.some(profile => profile.id === baseProfile?.profileName); group.append(node(document, 'summary', `เสียงที่โคลนไว้ (${clones.length})`)); const cards = node(document, 'div'); cards.className = 'tmrw-v3-voice-preset-cards'; for (const profile of clones) { const row = node(document, 'div'); row.className = 'tmrw-v3-voice-preset-row'; row.setAttribute('aria-selected', String(profile.id === baseProfile?.profileName)); const choose = node(document, 'button'); choose.type = 'button'; choose.append(node(document, 'strong', profile.name || profile.id), node(document, 'small', profile.language === 'ja' ? 'เสียงโคลน • Japanese' : 'เสียงโคลน • English')); choose.addEventListener('click', () => onSaveBaseName?.(profile.id)); const play = node(document, 'button', previewBusyId === profile.id ? '…' : '▶'); play.type = 'button'; play.className = 'tmrw-v3-voice-preview'; play.disabled = !runtimeReady || previewBusyId === profile.id; play.addEventListener('click', () => onPreviewVoice?.(profile.id, profile.language || 'en')); row.append(choose, play); cards.append(row); } group.append(cards); selector.append(group); } base.append(selector);
    const clone = node(document, 'div'); clone.className = 'tmrw-v3-voice-clone'; const upload = node(document, 'input'); upload.type = 'file'; upload.accept = 'audio/*,video/*'; upload.hidden = true; const uploadButton = node(document, 'button', 'สร้างเสียงใหม่จากคลิป'); uploadButton.type = 'button'; uploadButton.disabled = !runtimeConfigured || typeof onUploadClone !== 'function' || (cloneState && !['failed','complete'].includes(cloneState.phase)); uploadButton.addEventListener('click', () => upload.click?.()); upload.addEventListener('change', () => { const file = upload.files?.[0]; if (file) onUploadClone?.(file, selectedIdentity); }); clone.append(uploadButton, upload, node(document, 'small', 'อัปโหลดคลิป ระบบจะถอดเสียงให้อัตโนมัติ')); if (cloneState && cloneState.identity?.actorId === selectedIdentity.actorId) { const progress = node(document, 'section'); progress.className = `tmrw-v3-voice-clone-state is-${cloneState.phase}`; progress.append(node(document, 'strong', cloneState.label || 'กำลังทำงาน…')); if (cloneState.phase === 'review') { const name = node(document, 'input'); name.value = cloneState.name || selectedIdentity.label; name.placeholder = 'ชื่อเสียง'; const transcript = node(document, 'textarea'); transcript.value = cloneState.transcript || ''; transcript.placeholder = 'ข้อความที่ได้จากคลิป'; const confirm = node(document, 'button', 'ยืนยันและสร้างเสียง'); confirm.type = 'button'; confirm.addEventListener('click', () => onConfirmClone?.({ name: name.value, transcript: transcript.value })); progress.append(node(document, 'small', 'แก้ข้อความเฉพาะจุดที่ถอดผิด'), name, transcript, confirm); } clone.append(progress); } base.append(clone);
    base.append(toggleRow(document, { label: 'ล็อกการตั้งค่านี้', pressed: Boolean(baseProfile?.lockedByUser), setting: 'voice-base-lock', onClick: onToggleBaseLock, disabled: !runtimeConfigured })); profiles.append(base);

    const specific = node(document, 'section'); specific.className = 'tmrw-v3-voice-profile-card'; specific.dataset.voiceProfileKind = 'instance-override'; specific.append(copyBlock(document, 'เฉพาะตัวละครนี้', 'ใช้ค่าต่างจากค่าเสียงหลักในเรื่องนี้'));
    specific.append(toggleRow(document, { label: 'ใช้ค่าปรับเฉพาะ', pressed: Boolean(instanceOverride?.enabled), setting: 'voice-instance-override', onClick: onToggleOverride, disabled: !runtimeConfigured }));
    if (instanceOverride?.enabled) { specific.append(textField(document, { value: instanceOverride.fields?.profileName || '', placeholder: 'ชื่อโปรไฟล์เสียง', actionLabel: 'บันทึก', action: onSaveOverrideName, disabled: !runtimeConfigured })); }
    profiles.append(specific);
  }
  root.append(profiles);

  const testCard = node(document, 'section'); testCard.className = 'tmrw-v3-voice-card tmrw-v3-voice-test-card'; const test = node(document, 'button', 'ตรวจระบบ'); test.type = 'button'; test.dataset.voiceAction = 'test-voice'; test.disabled = runtimeBusy || capability?.testVoiceEnabled !== true; test.setAttribute('aria-disabled', String(test.disabled)); if (!test.disabled) test.addEventListener('click', () => onTestRuntime?.()); testCard.append(copyBlock(document, 'ตรวจการเชื่อมต่อเสียง', runtimeBusy ? 'กำลังตรวจ…' : (runtimeReady ? 'พร้อมใช้งานแล้ว' : 'แตะเพื่อตรวจ Runtime')), test); root.append(testCard);

  return root;
}
